"""Check exact actual numeric counter matrix, original parser and source subject."""
import argparse,hashlib,json,re,shutil
from pathlib import Path
import check_targets as driver
p=Path(__file__).resolve().parent
parser=argparse.ArgumentParser();parser.add_argument('--source',type=Path,required=True);parser.add_argument('--out',type=Path,required=True);a=parser.parse_args();source=a.source.resolve()
sr=json.loads((source/'receipt.json').read_text())
if sr['outcome']!='Checked' or not sr['fresh_kernel_replay']:raise driver.ProofError('complete genuine checked counter source required')
out=a.out.resolve();out.mkdir(exist_ok=False);shutil.copyfile(__file__,out/'driver.py');inputs=out/'proof-inputs';inputs.mkdir();q=Path('experiments/transition-study033/generated/counter-matrix-quote-001');quote=json.loads((q/'quote.json').read_text());raw=Path(quote['source']).read_bytes()
if hashlib.sha256(raw).hexdigest()!=quote['source_sha256'] or not quote['independent_inverse_byte_equal']:raise driver.ProofError('actual matrix quote identity missing')
targets={}
for n in ['ActualCounterMatrixConstants']+[f'ActualCounterMatrixData{i}' for i in range((len(quote['groups'])+63)//64)]:
 shutil.copyfile(q/(n+'.lean'),inputs/(n+'.lean'));targets[n]=[]
code=['import ActualCounterMatrixData0','import ActualCounterMatrixData1','import ActualCounterMatrixData2','import ActualCounterIR','import ActualCounterBytes','import Core033.WordMatrixShape','import Core033.WordSourceValidity','import Core033.MatrixRowBlocks','import Core033.KernelDecide','namespace CheckedCounterMatrix','open Core033 ActualCounterMatrixData','set_option Elab.async false','set_option maxRecDepth 16384','set_option maxHeartbeats 8000000','def actualMatrix : R1CS.Matrix := ⟨actualModulus,actualVariableCount,actualInputPorts,actualPrivatePorts,actualOutputPorts,actualConstantOne,['+','.join(f'actualRows{i}' for i in range(len(quote['groups'])))+'].flatten⟩','theorem matrix_exact : actualMatrix=WordMatrix.compile actualModulus ActualCounterIR.program := by core033_kernel_decide','theorem field_identity : actualModulus=R1CS.pallasScalarModulus := by decide','theorem program_valid : ActualCounterIR.program.Valid :=','  WordSourceValidity.safe_program_valid _ ((WordSource.check_safe_exact _).mp ActualCounterIR.safe_checked)','theorem matrix_shape : actualMatrix.wellFormed=true := by','  rw [matrix_exact]','  apply WordMatrixShape.complete_well_formedness','  · decide','  · decide','  · decide','  · exact program_valid',f'theorem row_stats : actualMatrix.rows.length=11384 ∧ MatrixRowBlocks.rowsWeight actualMatrix.rows={sum(g["encoded_bytes"] for g in quote["groups"])} := by core033_kernel_decide','theorem port_stats : actualMatrix.inputPorts.length=4 ∧ actualMatrix.privatePorts.length=11318 ∧ actualMatrix.outputPorts.length=8 := by core033_kernel_decide',f'theorem binary_size : (MatrixCodec.encode actualMatrix).length={len(raw)} := by','  rw [MatrixRowBlocks.encoded_matrix_size,port_stats.1,port_stats.2.1,port_stats.2.2,row_stats.2]','theorem actual_parsed : Matrix.parse (MatrixCodec.encode actualMatrix)=some actualMatrix := by','  apply MatrixCodecPayload.matrix_roundtrip actualMatrix matrix_shape','  · rw [row_stats.1];decide','  · rw [binary_size];decide','theorem exact_program_meaning (inputs : Nat → WordIR.Word) : ActualCounterIR.program.eval inputs=CounterProgram.expected inputs := by','  rw [ActualCounterIR.ir_exact,CounterProgram.program_meaning]','theorem actual_output_sound {F : Type} [Field F] [CharP F R1CS.pallasScalarModulus]','    (valuation : Nat → F) (inputs : Nat → WordIR.Word)','    (satisfied : actualMatrix.satisfies valuation)','    (inputValues : ∀ i,i<4 → valuation (WordField.packed i)=((inputs i).toNat : F))','    (position register : Nat) (found : ActualCounterIR.program.outputs[position]?=some register) :','    valuation (WordMatrix.outputBase ActualCounterIR.program+position)=','      ((WordIR.run ActualCounterIR.program.inputCount ActualCounterIR.program.operations inputs register).toNat : F) := by','  have standard : (WordMatrix.compile R1CS.pallasScalarModulus ActualCounterIR.program).satisfies valuation := by','    rw [←field_identity,←matrix_exact];exact satisfied','  exact WordMatrix.matrix_sound_at_output R1CS.modulus_larger_than_word ActualCounterIR.program program_valid','    valuation inputs standard inputValues position register found','end CheckedCounterMatrix']
(inputs/'CheckedCounterMatrix.lean').write_text('\n'.join(code)+'\n');targets['CheckedCounterMatrix']=['CheckedCounterMatrix.'+n for n in re.findall(r'^theorem ([A-Za-z_0-9]+)', '\n'.join(code),re.M)]
# The source receipt already fresh-checks these imports. Re-audit its named targets
# alongside the new actual matrix and fresh-replay the combined closure.
source_report=json.loads((source/'kernel/report.json').read_text());targets['CheckedCounterMatrix'] += [t['target'] for t in source_report['theorems']]
r=driver.check_modules(inputs,targets,out/'kernel',audit_source=p/'Audit.lean',dependency_paths=sorted((p/'.lake/packages').glob('*/.lake/build/lib/lean')),seeded_modules=[source/'kernel/compiled'])
if Path(quote['source']).read_bytes()!=raw:raise driver.ProofError('actual matrix changed')
(out/'matrix.bin').write_bytes(raw)
receipt={'format_version':'core033.actual-counter-matrix.v1','outcome':r['outcome'],'targets':len(r['theorems']),'fresh_kernel_replay':r['fresh_kernel_replay'],'matrix_sha256':hashlib.sha256(raw).hexdigest(),'matrix_bytes':len(raw),'source_receipt_sha256':hashlib.sha256((source/'receipt.json').read_bytes()).hexdigest(),'scope':'actual full counter source/matrix and original bounded binary parser; no whole K/backend','release_relation_complete':False,'g1_pass':False}
(out/'receipt.json').write_text(json.dumps(receipt,indent=2,sort_keys=True)+'\n');print(json.dumps(receipt))
